const {chromium}=require('playwright');const assert=require('assert');
const base='http://127.0.0.1:8080/?participant=050&build=500audit';
const banned=/prototype|p0 readiness|production (system|engine|keneflex brain)|product[- ]intelligence|future commerce|support role|second support|role being completed|still completing|research preview|commercial firewall|re[- ]?solve|keneflex should|treatment value/i;
const stories=[];const regions=['right wrist and thumb','left wrist','right thumb','left shoulder','right knee','left ankle','right heel','left elbow','neck','lower back'];const triggers=['phone and computer use','typing','scrolling','larger movements','stairs','walking','morning walking','gripping and lifting','morning','lifting'];for(let i=0;i<500;i++){const j=i%10;stories.push(`My ${regions[j]} has been sore for ${2+(i%5)} weeks. ${triggers[j]} makes it worse. ${i%3?'No injury.':'It came on gradually.'}`)}
(async()=>{const browser=await chromium.launch({headless:true,channel:'chrome'});const page=await browser.newPage({viewport:{width:390,height:844}});const fail=[];for(let i=0;i<500;i++){try{await page.goto(base+'&case='+(i+1),{waitUntil:'domcontentloaded',timeout:10000});await page.waitForSelector('#opening',{timeout:3000});await page.evaluate(story=>{state.opening=story;document.querySelector('#intro')?.classList.add('hidden');document.querySelector('#chatView')?.classList.add('hidden');document.querySelector('#solutionView')?.classList.remove('hidden');if(typeof showSolution==='function')showSolution();window.KFX049?.clean();},stories[i]);await page.waitForTimeout(25);const a=await page.evaluate(()=>{const root=document.querySelector('#solutionView');const text=(root?.innerText||'').replace(/\s+/g,' ');const total=document.querySelector('#total')?.textContent?.trim();const buy=document.querySelector('.kfxBuy');const visible=buy&&buy.getClientRects().length>0;const prices=[...document.querySelectorAll('#solutionView .planItem:not(.removed) .price')].map(e=>parseFloat((e.textContent||'').replace(/[^0-9.]/g,''))).filter(Number.isFinite);return{text,total,buy:buy?.textContent||'',visible,sum:prices.reduce((a,b)=>a+b,0)};});assert(a.total,'missing total');assert(a.visible,'buy CTA missing/hidden');assert(a.buy.includes(a.total),'buy CTA does not repeat total');assert(!banned.test(a.text),'internal/development language visible');const n=parseFloat(a.total.replace(/[^0-9.]/g,''));assert(Math.abs(n-a.sum)<.011,`total mismatch ${n} vs ${a.sum}`);await page.click('.kfxBuy');await page.waitForSelector('.kfxCheckoutOverlay',{timeout:2000});const c=await page.evaluate(()=>({text:(document.querySelector('.kfxCheckout')?.innerText||'').replace(/\s+/g,' '),total:document.querySelector('.kfxCheckout .totalx span:last-child')?.textContent?.trim(),final:!!document.querySelector('[data-kfx-final]')}));assert(c.total===a.total,'cart total differs');assert(c.final,'final checkout action missing');assert(!banned.test(c.text),'cart leaks internal language');await page.click('[data-kfx-final]');await page.waitForSelector('[data-kfx-close2]',{timeout:2000});pass=true;}catch(e){fail.push({subject:i+1,error:e.message});}finally{await page.evaluate(()=>document.querySelector('.kfxCheckoutOverlay')?.remove()).catch(()=>{});} }
await browser.close();console.log(JSON.stringify({subjects:500,failed:fail.length,sample:fail.slice(0,30)},null,2));if(fail.length)process.exit(1);})();
